expected.skos:
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<https://a.example/> dcterms:creator "Andrei N. Besleaga" ;
    dcterms:description "A node for the SKOS case." ;
    dcterms:license "CC0-1.0" ;
    dcterms:title "Example node" ;
    a skos:ConceptScheme ;
    skos:hasTopConcept <https://a.example/concepts/alpha/> , <https://a.example/concepts/gamma/> , <https://a.example/lessons/les/> .

<https://a.example/clusters/grp/> a skos:Collection ;
    skos:definition "A cluster of letters for the case."@en ;
    skos:member <https://a.example/concepts/alpha/> , <https://a.example/concepts/beta/> ;
    skos:prefLabel "Letters"@en .

<https://a.example/concepts/alpha/> a skos:Concept ;
    skos:altLabel "A one"@en ;
    skos:definition "The first letter of the Greek alphabet."@en ;
    skos:inScheme <https://a.example/> ;
    skos:narrower <https://a.example/concepts/beta/> ;
    skos:prefLabel "Alpha"@en ;
    skos:related <https://a.example/concepts/gamma/> ;
    skos:topConceptOf <https://a.example/> .

<https://a.example/concepts/beta/> a skos:Concept ;
    skos:broader <https://a.example/concepts/alpha/> ;
    skos:definition "The second letter of the Greek alphabet."@en ;
    skos:inScheme <https://a.example/> ;
    skos:prefLabel "Beta"@en .

<https://a.example/concepts/gamma/> a skos:Concept ;
    skos:inScheme <https://a.example/> ;
    skos:prefLabel "Gamma"@en ;
    skos:related <https://a.example/concepts/alpha/> ;
    skos:topConceptOf <https://a.example/> .

<https://a.example/lessons/les/> a skos:Concept ;
    skos:inScheme <https://a.example/> ;
    skos:prefLabel "A lesson"@en ;
    skos:topConceptOf <https://a.example/> .
